<script setup>
import {ref} from 'vue';import {useRouter} from 'vue-router';import {BookOpen,ArrowRight} from '@lucide/vue';import {authenticate} from '../lib/store';
const router=useRouter(),mode=ref('login'),name=ref(''),email=ref(''),password=ref(''),busy=ref(false),error=ref('');
async function submit(){busy.value=true;error.value='';try{await authenticate(mode.value,{email:email.value,password:password.value,...(mode.value==='register'?{name:name.value}:{})});router.replace('/');}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><div class="auth-layout"><section class="auth-intro"><BookOpen :size="38" :stroke-width="1.3"/><h1>Menos procura.<br>Mais aventura.</h1><p>Prepare o repertório do seu personagem e tenha cada magia ao alcance de um toque.</p><div class="auth-detail"><span>01</span><p>Escolha seu personagem e as magias da sua classe.</p></div><div class="auth-detail"><span>02</span><p>Abra a descrição completa enquanto joga.</p></div><div class="auth-detail"><span>03</span><p>Acrescente suas próprias magias e compêndios.</p></div></section>
<section class="auth-form"><span class="section-caption">Bem-vindo ao seu grimório</span><h2>{{mode==='login'?'Entre na sua conta':'Crie sua conta'}}</h2><p class="muted">Seu repertório fica guardado para a próxima sessão.</p><div class="tabs"><button :class="{active:mode==='login'}" @click="mode='login';error=''">Entrar</button><button :class="{active:mode==='register'}" @click="mode='register';error=''">Criar conta</button></div>
<form @submit.prevent="submit"><label v-if="mode==='register'">Seu nome<input v-model="name" autocomplete="name" required maxlength="200"/></label><label>Email<input v-model="email" type="email" autocomplete="email" required maxlength="254" placeholder="voce@exemplo.com"/></label><label>Senha<input v-model="password" type="password" :autocomplete="mode==='login'?'current-password':'new-password'" required :minlength="mode === 'register' ? 8 : undefined" :pattern="mode === 'register' ? '(?=.*\\p{Lu})(?=.*\\p{Ll})(?=.*[0-9]).{8,256}' : undefined" maxlength="256" :title="mode === 'register' ? 'Use pelo menos 8 caracteres, uma letra maiúscula, uma letra minúscula e um número.' : undefined"/><small v-if="mode==='register'">Use pelo menos 8 caracteres, uma letra maiúscula, uma letra minúscula e um número.</small></label><p v-if="error" class="alert" role="alert">{{error}}</p><button class="button primary full" :disabled="busy">{{busy?'Aguarde…':mode==='login'?'Entrar no grimório':'Criar meu grimório'}}<ArrowRight :size="18"/></button></form></section></div></template>
